/**
 * @method
 * @name scwin.moveToList
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.moveToList = function (div) {
    /* sdd-asis-lifecycle:begin moveToList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const sObj = $c.util.getComponent('slc_isuCdList').options;
    let iTxt = "", iVal = "";
    for (let i = 0, j = tObj.length; i < sObj.length; i++) {
        if ((sObj[i].selected && div != 2) || div == 2) {
            iTxt = sObj[i].text;
            iVal = sObj[i].value;
            let isExist = false;
            for (k = 0; k < tObj.length; k++) {
                if (iVal === tObj[k].value) {
                    isExist = true;
                    continue;
                }
            }
            if (!isExist) {
                tObj[j] = new Option(iTxt, iVal);
            }
            j++;
            sObj[i].selected = false;
        }
    }
    scwin.BumpUp($c.util.fieldEl('slc_tgtIsuCdList', 'tgt_isuCd_list'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.removeList
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.removeList = function (div) {
    /* sdd-asis-lifecycle:begin removeList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const Obj = $c.util.getComponent('slc_tgtIsuCdList');
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const len = tObj.length;
    if (div == 1) {
        if (scwin.selectedItem(Obj)) {
            for (var i = 0; i < Obj.options.length; i++) {
                if (Obj.options[i].selected && Obj.options[i] !== "") {
                    Obj.options[i].value = "";
                    Obj.options[i].text = "";
                }
            }
            scwin.BumpUp(Obj);
        }
    } else {
        if (div == 2) {
            for (var i = len - 1; i >= 0; i--) {
                tObj[i].removeNode();
            }
        }
    }
    for (var i = 0; i < tObj.length; i++) {
        tObj[i].selected = false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.BumpUp
 * @author Inswave
 * @date 2026. 09. 29
 * @param abox
 * @returns
 * @hidden N
*/
scwin.BumpUp = function (abox) {
    /* sdd-asis-lifecycle:begin BumpUp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < abox.options.length; i++) {
        if (abox.options[i].value === "") {
            for (let j = i; j < abox.options.length - 1; j++) {
                abox.options[j].value = abox.options[j + 1].value;
                abox.options[j].text = abox.options[j + 1].text;
            }
            const ln = i;
            break;
        }
    }
    if (ln < abox.options.length) {
        abox.options.length -= 1;
        scwin.BumpUp(abox);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selectedItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.selectedItem = function (obj) {
    /* sdd-asis-lifecycle:begin selectedItem — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].selected) {
            return true;
        }
    }
    return false;
    /* sdd-asis-lifecycle:end */
};



